import {MADARA_META as META} from './madara-meta.js';
import {madaraPose} from '../characters/madara.js';
import {personalCaster} from '../engine/personal-ultimate.js';
import {cinematicSteps} from '../engine/ultimate-rules.js';
export function madaraSprite(ctx,images,key,row,col,x,y,scale=1,angle=0,face=1){const m=META[key],im=images[key];if(!m||!im?.complete||!im.naturalWidth)return;row=Math.max(0,Math.min(m.rows-1,row));col=Math.max(0,Math.min(m.rowCounts[row]-1,col));const [w,h]=m.frameSize,[px,py]=m.pivot;ctx.save();ctx.translate(x,y);ctx.rotate(angle);ctx.scale(scale*(face<0?-1:1),scale);ctx.drawImage(im,col*w,row*h,w,h,-px,-py,w,h);ctx.restore();}
export function drawMadaraActor(ctx,images,d,f,hurt=false,override=null){let p=madaraPose(f,hurt),y=f.y;const c=personalCaster(d,f);
 if(f.introAge!=null){const n=Math.min(7,Math.floor(f.introAge/2.5*8));p={key:'madara_intro',row:Math.floor(n/4),frame:n%4};y-=Math.max(0,1-f.introAge/1.65)*42;}
 else if(c||override){const u=d.personalUltimate?.cinematic||d.teamUltimate?.cinematic;p={key:'madara_ultimate_actor',row:0,frame:u?Math.min(3,Math.floor(u.elapsed/cinematicSteps(u)*4)):3};}
 if(f.state==='defeat')p={key:'madara',row:7,frame:Math.min(3,Math.floor((d.tick-(f.deathTick??d.tick))/7))};
 madaraSprite(ctx,images,p.key,p.row,p.frame,f.x,y,.86,0,f.face);
}
export function drawMadaraBack(ctx,images,d,clock=0){for(const f of d.fighters)if(f.id==='madara'&&f.hp>0){if(f.introAge!=null){const p=f.introAge/2.5;ctx.save();ctx.globalAlpha=.72;madaraSprite(ctx,images,'madara_intro_vfx',0,Math.min(3,Math.floor(p*4)),f.x,f.y+2,.65);ctx.restore();}else if(f.sixPathsAwakened){ctx.save();ctx.globalAlpha=.2;madaraSprite(ctx,images,'madara_intro_vfx',0,2,f.x,f.y,.38);ctx.restore();}}}
function warning(ctx,x,y,radius,clock){ctx.save();ctx.strokeStyle='#d799ff';ctx.fillStyle='#9e50ff12';ctx.lineWidth=2;ctx.setLineDash([10,7]);ctx.beginPath();ctx.ellipse(x,y,radius,radius*.58,0,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=.55+.25*Math.sin(clock*10);ctx.beginPath();ctx.ellipse(x,y,radius*.72,radius*.42,0,0,Math.PI*2);ctx.stroke();ctx.restore();}
export function drawMadaraMeteor(ctx,images,x,y,progress,impact=false,reduced=false){if(impact){madaraSprite(ctx,images,'madara_ultimate_vfx',1,Math.min(3,Math.floor(progress*4)),x,y-25,reduced?.88:1.1);}else{const p=Math.max(0,Math.min(1,progress));madaraSprite(ctx,images,'madara_ultimate_vfx',0,Math.min(3,Math.floor(p*4)),x-80*(1-p),y-320*(1-p)-40,1.05);}}
export function drawMadaraWorld(ctx,images,d,clock=0,reduced=false){for(const f of d.fighters)if(f.id==='madara')for(const s of f.limboShadows||[]){ctx.save();ctx.globalAlpha=.4*Math.min(1,s.life/.4);ctx.filter='sepia(.5) saturate(2) hue-rotate(220deg)';if(!reduced){ctx.shadowColor='#c88aff';ctx.shadowBlur=12;}madaraSprite(ctx,images,'madara',s.state==='melee'?2:1,Math.floor(s.age*8)%4,s.x,s.y,1.02,0,s.face);ctx.restore();}
 const a=d.personalUltimate?.attack;if(a?.kind!=='meteor')return;if(a.phase==='warning')warning(ctx,a.targetX,a.targetY,200,clock);else{const p=(d.tick-a.launch)/42;if(p<1)drawMadaraMeteor(ctx,images,a.targetX,a.targetY,p,false,reduced);else drawMadaraMeteor(ctx,images,a.targetX,a.targetY,(d.tick-a.impactTick)/60,true,reduced);}}
export function drawMadaraTeamWorld(ctx,images,d,clock=0,reduced=false){const a=d.teamUltimate?.attack;if(!a)return;if(a.phase==='warning')warning(ctx,a.targetX,a.targetY,160,clock);else if(a.phase==='travel')drawMadaraMeteor(ctx,images,a.targetX,a.targetY,(d.tick-a.launch)/(a.impact-a.launch),false,reduced);else drawMadaraMeteor(ctx,images,a.targetX,a.targetY,(d.tick-a.impact)/48,true,reduced);}
export function drawMadaraShot(ctx,images,s,x,y,clock){const angle=Math.atan2(s.vy,s.vx);if(s.kind==='lightfang'){
 const im=images.madara_vfx,m=META.madara_vfx;if(!im?.complete||!im.naturalWidth)return;
 const frame=1+Math.floor(clock*10)%2,b=m.bounds[1][frame],[w,h]=m.frameSize,fromX=s.fromX??x-Math.cos(angle)*220,fromY=s.fromY??y+28-Math.sin(angle)*220;
 const length=Math.max(12,Math.min(650,Math.hypot((s.x??x)-fromX,(s.y??y+28)-fromY)+15));
 ctx.save();ctx.translate(fromX,fromY-78);ctx.rotate(angle);ctx.scale(length/(b[2]-b[0]),.55);ctx.drawImage(im,frame*w,h,w,h,-b[0],-(b[1]+b[3])/2,w,h);ctx.restore();
 }else madaraSprite(ctx,images,'madara_vfx',0,Math.floor(clock*10)%3,x,y,s.kind==='madaraorb'?.25:.5,angle);}
export function drawMadaraBurst(ctx,images,b){const p=1-b.life/b.max;if(b.action==='meteor')return;madaraSprite(ctx,images,'madara_vfx',b.action==='limbo'?2:b.action==='fang'?1:0,b.action==='orb'?3:Math.min(3,Math.floor(p*4)),b.x,b.y,b.action==='limbo'?.65:.5);}
export function drawMadaraChat(ctx,images,c,line='Tengai Shinsei!',reduced=false){const p=c.elapsed/cinematicSteps(c),row=p<.5?0:1,col=1,m=META.madara_dialogue,b=m.bounds[row][col],w=b[2]-b[0],h=b[3]-b[1],scale=Math.min(760/w,180/h),cx=(b[0]+b[2])/2,cy=(b[1]+b[3])/2;ctx.save();ctx.globalAlpha=Math.max(0,Math.min(1,p*10,(1-p)*12));madaraSprite(ctx,images,'madara_dialogue',row,col,480-(cx-m.pivot[0])*scale,438-(cy-m.pivot[1])*scale,scale);const x=480+w*scale*.17;ctx.fillStyle='#f5deff';ctx.textAlign='center';ctx.font='bold 14px Georgia';ctx.fillText('MADARA · SIX PATHS',x,410,w*scale*.5);ctx.font='bold 20px Georgia';ctx.fillText(line,x,449,w*scale*.5);ctx.restore();}
export function drawMadaraCinematic(ctx,images,d,reduced=false){const c=d.personalUltimate?.cinematic;if(c?.kind==='meteor')drawMadaraChat(ctx,images,c,undefined,reduced);}
